-- Phase 9: SEO content for every SEO field. Safe to re-run (it overwrites only the SEO fields it lists).
-- Run in Supabase > SQL Editor AFTER schema.sql and phase7_seo.sql. Then redeploy so the static pages pick it up.

-- 1) Site-wide SEO + page-by-page SEO (Admin > Settings > SEO & footer)
update public.site_settings
set value = jsonb_set(value, '{seo}', coalesce(value->'seo', '{}'::jsonb) || $j${"titleTemplate": "%s — Muhammad Zeeshan Haider", "defaultDescription": "Muhammad Zeeshan Haider is a developer building websites, full-stack apps, educational platforms and management systems that solve real problems.", "keywords": "Muhammad Zeeshan Haider, Zeeshan Haider developer, web developer Pakistan, full-stack developer, freelance web developer, website development, full-stack web applications, React developer, Supabase developer, educational platform development, college management system, school management system, learning management system, custom software development, management systems, student developer portfolio, web application development, digital solutions builder, hire web developer, ed-tech web apps", "locale": "en_US", "ogImage": "/og-default.png", "pages": {"/": {"title": "Muhammad Zeeshan Haider | Web & Full-Stack Developer", "description": "Muhammad Zeeshan Haider builds websites, full-stack apps, educational platforms and management systems that turn ideas into working solutions.", "image": "/og-default.png"}, "/about": {"title": "About Muhammad Zeeshan Haider — Student Developer", "description": "Meet Muhammad Zeeshan Haider, a student developer passionate about programming, educational technology and useful web applications."}, "/projects": {"title": "Projects & Case Studies — Zeeshan Haider", "description": "Explore web apps and digital systems by Muhammad Zeeshan Haider: college websites, study platforms, classroom tools and educational products."}, "/services": {"title": "Web Development & Custom Software Services", "description": "Website development, full-stack applications, educational platforms, management systems and custom digital solutions built around your needs."}, "/experience": {"title": "Developer Journey — Muhammad Zeeshan Haider", "description": "Follow Muhammad Zeeshan Haider's journey from early curiosity about technology to building full-stack, institutional and educational systems."}, "/blog": {"title": "Blog — Web Development & Tech Insights", "description": "Articles by Muhammad Zeeshan Haider on web development, programming, educational technology and lessons learned while building real projects."}, "/testimonials": {"title": "Testimonials & Feedback — Zeeshan Haider", "description": "Read feedback from people who have worked with or learned from Muhammad Zeeshan Haider on web development and digital projects."}, "/contact": {"title": "Contact Muhammad Zeeshan Haider — Web Developer", "description": "Get in touch with Muhammad Zeeshan Haider about web development, full-stack projects, collaborations or general questions."}, "/book": {"title": "Book a Session with Muhammad Zeeshan Haider", "description": "Book a short video or phone session with Muhammad Zeeshan Haider to discuss a project, get technical advice or explore a collaboration."}, "/start-project": {"title": "Start a Project — Hire a Web Developer", "description": "Tell Muhammad Zeeshan Haider about your website, web app or management system and get a clear path from idea to launch."}}}$j$::jsonb, true)
where key = 'site';

